_theme.customCss:
.xt-root {
    --xt-bg: #0d0d0f;
    --xt-text: #e0e0e0;
    --xt-text-sub: #888899;
    --xt-text-muted: #444455;
    --xt-accent: #ff2a40;
    --xt-accent-bg: rgba(255, 42, 64, 0.1);
    --xt-border: rgba(255, 42, 64, 0.35);
    --xt-radius: 16px;
    --xt-glow-color: rgba(255, 42, 64, 0.35);
    background: var(--xt-bg);
    border: 1px solid var(--xt-border);
    box-shadow: 0 16px 40px rgba(0, 0, 0, 0.85);
    padding: 16px;
}

.xt-avatar {
    border: 2px solid var(--xt-accent);
    box-shadow: 0 0 10px rgba(255, 42, 64, 0.4);
}
.xt-name {
    color: var(--xt-accent);
    font-weight: bold;
    font-size: 16px;
    letter-spacing: 1px;
}

.xt-badge {
    background: var(--xt-accent-bg);
    color: var(--xt-accent);
    border: 1px solid var(--xt-border);
    border-radius: 12px;
    font-size: 11px;
    padding: 2px 10px;
    letter-spacing: 1px;
    font-weight: bold;
}

.xt-text-metaInfo {
    color: var(--xt-text-sub);
    font-size: 11px;
    margin-top: 4px;
    margin-bottom: 12px;
    display: block;
}

.xt-tags {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-bottom: 12px;
}
.xt-tag {
    background: rgba(255, 42, 64, 0.04);
    color: var(--xt-accent);
    border: 1px solid var(--xt-border);
    border-radius: 20px;
    padding: 8px 14px;
    font-size: 12px;
    line-height: 1.5;
    text-align: left;
    word-break: break-all;
}

.xt-card {
    background: rgba(18, 18, 22, 0.95);
    border: 1px solid var(--xt-border);
    border-radius: 14px;
    padding: 14px;
    margin-top: 12px;
}
.xt-card-title {
    color: var(--xt-accent);
    font-size: 12px;
    font-weight: bold;
    border-bottom: 1px dashed var(--xt-border);
    padding-bottom: 8px;
    margin-bottom: 12px;
    letter-spacing: 1px;
}

.xt-text {
    color: #d0d0d5;
    font-size: 13px;
    line-height: 1.85;
    letter-spacing: 0.5px;
}

.xt-footer {
    color: #444455;
    font-size: 10px;
    letter-spacing: 2px;
    text-align: center;
    margin-top: 12px;
}
